//! 🏛️ Admitted Model spatial placements, complete classes, typed properties and relations.
use super::{SemioModelSnapshot,SpatialNode,SpatialKind,SemioModelElement,ElementClass,GeometryRef,PropertySet,Property,PsetValue,ModelRelation,RelationKind,SemioTransform,SemioPoint3,SemioQuaternion,STDIO_SEMIOMODEL_DOCUMENT_SCHEMA};
use crate::standards::v1::subsets::base::schema::snapshot::native_decoding as native;
use semio_framework_value::native_decoding::NativeDecodeControl;
use store::sqlite_snapshot::{SqliteSnapshotControl,SqliteDatabaseLimits};
pub(super) fn decode(payload:&store::os_io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<SemioModelSnapshot,String>{native::decode(payload,STDIO_SEMIOMODEL_DOCUMENT_SCHEMA,control,binary,document)}
fn f64(reader:&mut store::ByteReader<'_>)->Result<f64,String>{reader.read_f64_le().map_err(|e|e.to_string())}
fn point(reader:&mut store::ByteReader<'_>)->Result<SemioPoint3,String>{Ok(SemioPoint3{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?})}
fn transform(reader:&mut store::ByteReader<'_>)->Result<SemioTransform,String>{Ok(SemioTransform{translation:point(reader)?,rotation:SemioQuaternion{x:f64(reader)?,y:f64(reader)?,z:f64(reader)?,w:f64(reader)?},scale:point(reader)?})}
fn option(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,String>{match reader.read_u8().map_err(|e|e.to_string())?{0=>Ok(None),1=>native::text(reader,control).map(Some),_=>Err("invalid Model native optional presence".into())}}
fn class_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<ElementClass,String>{Ok(match reader.read_u8().map_err(|e|e.to_string())?{0=>ElementClass::Wall,1=>ElementClass::Slab,2=>ElementClass::Column,3=>ElementClass::Beam,4=>ElementClass::Door,5=>ElementClass::Window,6=>ElementClass::Roof,7=>ElementClass::Stair,8=>ElementClass::Furniture,9=>ElementClass::Other{name:native::text(reader,control)?},_=>return Err("invalid Model native element class".into())})}
fn geometry_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<GeometryRef,String>{Ok(match reader.read_u8().map_err(|e|e.to_string())?{0=>GeometryRef::None,1=>GeometryRef::Brep{brep_id:native::text(reader,control)?},2=>GeometryRef::Mesh{mesh_id:native::text(reader,control)?},_=>return Err("invalid Model native geometry reference".into())})}
fn value_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<PsetValue,String>{Ok(match reader.read_u8().map_err(|e|e.to_string())?{0=>PsetValue::Text{value:native::text(reader,control)?},1=>PsetValue::Number{value:f64(reader)?},2=>PsetValue::Boolean{value:match reader.read_u8().map_err(|e|e.to_string())?{0=>false,1=>true,_=>return Err("invalid Model native property boolean".into())}},_=>return Err("invalid Model native property kind".into())})}
fn relation_binary(reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<RelationKind,String>{Ok(match reader.read_u8().map_err(|e|e.to_string())?{0=>RelationKind::Aggregates,1=>RelationKind::ContainedIn,2=>RelationKind::ConnectsTo,3=>RelationKind::FillsVoid,4=>RelationKind::VoidsElement,5=>RelationKind::Other{label:native::text(reader,control)?},_=>return Err("invalid Model native relation kind".into())})}
pub(crate) fn binary(body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioModelSnapshot,String>{let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|e.to_string())?!=1{return Err("unsupported Model native format".into())}let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::text(&mut reader,control)?;
let spatial=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{native::entities(entities,2,limits)?;let id=native::text(reader,control)?;let kind=match reader.read_u8().map_err(|e|e.to_string())?{0=>SpatialKind::Site,1=>SpatialKind::Building,2=>SpatialKind::Storey,3=>SpatialKind::Space,_=>return Err("invalid Model native spatial kind".into())};Ok(SpatialNode{id,kind,name:native::text(reader,control)?,parent_id:option(reader,control)?,placement:transform(reader)?})})?;
let elements=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,entities|{native::entities(entities,3,limits)?;let id=native::text(reader,control)?;let class=class_binary(reader,control)?;let placement=transform(reader)?;let geometry=geometry_binary(reader,control)?;let spatial_id=option(reader,control)?;let psets=native::binary_list(reader,control,limits,entities,|reader,control,entities|{let name=native::text(reader,control)?;let properties=native::binary_list(reader,control,limits,entities,|reader,control,_|Ok(Property{key:native::text(reader,control)?,value:value_binary(reader,control)?}))?;Ok(PropertySet{name,properties})})?;Ok(SemioModelElement{id,class,placement,geometry,spatial_id,psets})})?;
let relations=native::binary_list(&mut reader,control,limits,&mut entities,|reader,control,_|Ok(ModelRelation{id:native::text(reader,control)?,kind:relation_binary(reader,control)?,from:native::text(reader,control)?,to:native::text(reader,control)?}))?;if reader.remaining()!=0{return Err("Model native trailing bytes".into())}Ok(SemioModelSnapshot{schema,spatial,elements,relations})}
fn option_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<Option<String>,String>{if value=="[0]"{return Ok(None)}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err("invalid Model native optional presence".into())}native::hex_text(value,control).map(Some)}
fn point_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioPoint3,String>{let[x,y,z]=native::record(value,control)?;Ok(SemioPoint3{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?})}
fn transform_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<SemioTransform,String>{let[translation,rotation,scale]=native::record(value,control)?;let[x,y,z,w]=native::record(rotation,control)?;Ok(SemioTransform{translation:point_text(translation,control)?,rotation:SemioQuaternion{x:native::float(x,control)?,y:native::float(y,control)?,z:native::float(z,control)?,w:native::float(w,control)?},scale:point_text(scale,control)?})}
fn class_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<ElementClass,String>{Ok(match value{"WA"=>ElementClass::Wall,"SL"=>ElementClass::Slab,"CO"=>ElementClass::Column,"BE"=>ElementClass::Beam,"DO"=>ElementClass::Door,"WI"=>ElementClass::Window,"RO"=>ElementClass::Roof,"ST"=>ElementClass::Stair,"FU"=>ElementClass::Furniture,_=>{let value=value.strip_prefix("OT").ok_or("invalid Model native class")?;let[name]=native::record(value,control)?;ElementClass::Other{name:native::hex_text(name,control)?}}})}
fn geometry_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<GeometryRef,String>{if value=="N"{return Ok(GeometryRef::None)}let(tag,value)=value.split_at_checked(1).ok_or("Model geometry tag missing")?;let[id]=native::record(value,control)?;Ok(match tag{"B"=>GeometryRef::Brep{brep_id:native::hex_text(id,control)?},"M"=>GeometryRef::Mesh{mesh_id:native::hex_text(id,control)?},_=>return Err("invalid Model native geometry kind".into())})}
fn value_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<PsetValue,String>{let(tag,value)=value.split_at_checked(1).ok_or("Model property tag missing")?;let[value]=native::record(value,control)?;Ok(match tag{"T"=>PsetValue::Text{value:native::hex_text(value,control)?},"N"=>PsetValue::Number{value:native::float(value,control)?},"B"=>PsetValue::Boolean{value:match value{"0"=>false,"1"=>true,_=>return Err("invalid Model native property boolean".into())}},_=>return Err("invalid Model native property kind".into())})}
fn relation_text(value:&str,control:&mut NativeDecodeControl<'_>)->Result<RelationKind,String>{Ok(match value{"AG"=>RelationKind::Aggregates,"CI"=>RelationKind::ContainedIn,"CN"=>RelationKind::ConnectsTo,"FV"=>RelationKind::FillsVoid,"VE"=>RelationKind::VoidsElement,_=>{let value=value.strip_prefix("OT").ok_or("invalid Model native relation kind")?;let[label]=native::record(value,control)?;RelationKind::Other{label:native::hex_text(label,control)?}}})}
pub(crate) fn document(body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<SemioModelSnapshot,String>{let fields=native::fields(body,["schema","spatial","elements","relations"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;let schema=native::hex_text(fields[0].ok_or("Model native schema missing")?,control)?;
let spatial=native::text_list(fields[1].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{native::entities(entities,2,limits)?;let[id,kind,name,parent_id,placement]=native::record(value,control)?;let kind=match kind{"S"=>SpatialKind::Site,"B"=>SpatialKind::Building,"T"=>SpatialKind::Storey,"P"=>SpatialKind::Space,_=>return Err("invalid Model native spatial kind".into())};Ok(SpatialNode{id:native::hex_text(id,control)?,kind,name:native::hex_text(name,control)?,parent_id:option_text(parent_id,control)?,placement:transform_text(placement,control)?})})?;
let elements=native::text_list(fields[2].unwrap_or("[]"),control,limits,&mut entities,|value,control,entities|{native::entities(entities,3,limits)?;let[id,class,placement,geometry,spatial_id,psets]=native::record(value,control)?;let id=native::hex_text(id,control)?;let class=class_text(class,control)?;let placement=transform_text(placement,control)?;let geometry=geometry_text(geometry,control)?;let spatial_id=option_text(spatial_id,control)?;let psets=native::text_list(psets,control,limits,entities,|value,control,entities|{let[name,properties]=native::record(value,control)?;let name=native::hex_text(name,control)?;let properties=native::text_list(properties,control,limits,entities,|value,control,_|{let[key,value]=native::record(value,control)?;Ok(Property{key:native::hex_text(key,control)?,value:value_text(value,control)?})})?;Ok(PropertySet{name,properties})})?;Ok(SemioModelElement{id,class,placement,geometry,spatial_id,psets})})?;
let relations=native::text_list(fields[3].unwrap_or("[]"),control,limits,&mut entities,|value,control,_|{let[id,kind,from,to]=native::record(value,control)?;Ok(ModelRelation{id:native::hex_text(id,control)?,kind:relation_text(kind,control)?,from:native::hex_text(from,control)?,to:native::hex_text(to,control)?})})?;Ok(SemioModelSnapshot{schema,spatial,elements,relations})}
